/* Linear Algebra cards. Same fields as data/ps.js. */
(function(){
const R = String.raw;
addCards('la', [
/* ---------- Vector spaces ---------- */
{id:'subtest',t:'vs',u:'subsp',lv:1,k:'cond',name:'Subspace test',sheet:R`W\le V\iff \mathbf 0\in W,\ \ u+v\in W,\ \ cu\in W`,
 q:R`A non-empty subset \(W\subseteq\mathbb R^n\) is a subspace when:`,
 o:[R`It is closed under addition and scalar multiplication (so it contains \(\mathbf 0\))`,R`It contains at least one non-zero vector`,R`It is closed under addition only`,R`It contains the standard basis vectors`],a:0,
 why:R`Closure under both operations is the whole test; taking \(c=0\) shows \(\mathbf 0\) must be inside. A quick reject: if \(\mathbf 0\notin W\), it is not a subspace.`},
{id:'affine',t:'vs',u:'subsp',lv:1,k:'mcq',name:'Planes not through the origin',sheet:R`\{x: a^\top x=b\}\ \text{is a subspace}\iff b=0`,
 q:R`Is \(W=\{x\in\mathbb R^3: x_1+2x_2-x_3=3\}\) a subspace of \(\mathbb R^3\)?`,
 o:[R`No, because \(\mathbf 0\notin W\)`,R`Yes, it is a plane`,R`Yes, it is closed under addition`,R`Only if we restrict to \(x_1\ge0\)`],a:0,
 why:R`Plugging in \(\mathbf 0\) gives \(0\ne3\). A non-zero right-hand side shifts the plane off the origin, so sums leave it too.`},
{id:'squares',t:'vs',u:'subsp',lv:2,k:'mcq',name:'Squared coefficients',sheet:R`\{\alpha^2 v\}\ \text{is only a half-line, not a subspace}`,
 q:R`Fix a non-zero \(v\in\mathbb R^3\). Is \(W=\{\alpha^2 v:\alpha\in\mathbb R\}\) a subspace?`,
 o:[R`No: \(-v\) is not in W, so it fails scalar multiplication`,R`Yes: it is the span of \(v\)`,R`Yes: it contains \(\mathbf 0\)`,R`No: it does not contain \(\mathbf 0\)`],a:0,
 why:R`\(\alpha^2\ge0\), so W is the ray \(\{cv: c\ge0\}\). Multiplying by \(-1\) leaves it. Containing \(\mathbf 0\) is necessary but not sufficient.`},
{id:'solsp',t:'vs',u:'subsp',lv:2,k:'nat',name:'Dimension of a solution space',sheet:R`\dim\{x: Ax=\mathbf 0\}=n-\operatorname{rank}(A)`,
 q:R`Find the dimension of \(\{x\in\mathbb R^4: x_1+x_2=0,\ x_3-x_4=0,\ x_1+x_2+x_3-x_4=0\}\).`,n:{v:2},
 why:R`The third equation is the sum of the first two, so the rank is 2 and the dimension is \(4-2=2\).`},
{id:'indep',t:'vs',u:'lindep',lv:1,k:'fill',name:'Linear independence',sheet:R`c_1v_1+\dots+c_kv_k=\mathbf 0\Rightarrow c_1=\dots=c_k=0`,
 q:R`\(v_1,\dots,v_k\) are linearly independent when:`,f:R`c_1v_1+\dots+c_kv_k=\mathbf 0\ \Rightarrow\ \boxed{\;?\;}`,
 o:[R`\text{every }c_i=0`,R`\text{some }c_i=0`,R`\text{every }v_i=\mathbf 0`,R`\textstyle\sum c_i=0`],om:1,a:0,
 why:R`The only way to combine them into zero is the trivial way. If some non-trivial combination gives zero, one vector is a combination of the others.`},
{id:'toomany',t:'vs',u:'lindep',lv:1,k:'mcq',name:'Too many vectors',sheet:R`k>n\ \text{vectors in }\mathbb R^n\Rightarrow\text{dependent}`,
 q:R`Any set of 5 vectors in \(\mathbb R^4\) is:`,
 o:[R`Linearly dependent`,R`Linearly independent`,R`A basis of \(\mathbb R^4\)`,R`Independent unless one is zero`],a:0,
 why:R`\(\mathbb R^4\) has dimension 4, so at most 4 vectors can be independent.`},
{id:'zerovec',t:'vs',u:'lindep',lv:1,k:'mcq',name:'Sets containing zero',sheet:R`\mathbf 0\in\{v_i\}\Rightarrow\text{dependent}`,
 q:R`A set of vectors that contains the zero vector is:`,
 o:[R`Always linearly dependent`,R`Always independent`,R`Independent if the other vectors are`,R`A subspace`],a:0,
 why:R`\(1\cdot\mathbf 0=\mathbf 0\) is a non-trivial combination giving zero.`},
{id:'depk',t:'vs',u:'lindep',lv:1,k:'nat',name:'Dependence of two vectors',sheet:R`(a,b),(c,d)\ \text{dependent}\iff ad-bc=0`,
 q:R`For what \(k\) are \((2,3)\) and \((4,k)\) linearly dependent?`,n:{v:6},
 why:R`\(2k-12=0\Rightarrow k=6\). Then the second vector is twice the first.`},
{id:'onbasis',t:'vs',u:'basis',lv:1,k:'mcq',name:'Orthonormal sets and bases',sheet:R`\text{orthonormal}\Rightarrow\text{independent};\ \text{bases are not unique}`,
 q:R`Which statement is always true in \(\mathbb R^n\)?`,
 o:[R`Orthonormal vectors are linearly independent`,R`Linearly independent vectors are orthonormal`,R`\(\mathbb R^n\) has exactly one orthonormal basis`,R`Any n vectors form a basis`],a:0,
 why:R`Dot \(\sum c_iq_i=\mathbf 0\) with \(q_j\) to get \(c_j=0\). Rotating the standard basis gives other orthonormal bases, so it isn't unique.`},
{id:'symdim',t:'vs',u:'basis',lv:2,k:'fill',name:'Dimension of symmetric matrices',sheet:R`\dim\{A\in\mathbb R^{n\times n}:A=A^\top\}=\frac{n(n+1)}{2}`,
 f:R`\dim\{\text{symmetric } n\times n\}=\boxed{\;?\;}`,
 o:[R`\frac{n(n+1)}{2}`,R`\frac{n(n-1)}{2}`,R`n^2`,R`n`],om:1,a:0,
 why:R`Choose the diagonal and the upper triangle freely. Skew-symmetric matrices have zero diagonal, so they get \(n(n-1)/2\); together the two add to \(n^2\).`},
{id:'perp',t:'vs',u:'ortho',lv:1,k:'fill',name:'Orthogonal vectors',sheet:R`x\perp y\iff x^\top y=0`,
 f:R`x\perp y\iff\boxed{\;?\;}`,
 o:[R`x^\top y=0`,R`x^\top y=1`,R`xy^\top=0`,R`\|x\|=\|y\|`],om:1,a:0,
 why:R`The dot product is \(\|x\|\|y\|\cos\theta\), which is 0 at 90°. \(xy^\top\) is a matrix, not a number.`},
{id:'cosang',t:'vs',u:'ortho',lv:1,k:'fill',name:'Angle between vectors',sheet:R`\cos\theta=\frac{x^\top y}{\|x\|\,\|y\|}`,
 f:R`\cos\theta=\frac{x^\top y}{\boxed{\;?\;}}`,
 o:[R`\|x\|\,\|y\|`,R`\|x\|^2\|y\|^2`,R`x^\top x`,R`\|x+y\|`],om:1,a:0,
 why:R`Normalise both vectors. Cauchy–Schwarz, \(|x^\top y|\le\|x\|\|y\|\), keeps the ratio in \([-1,1]\).`},
{id:'pyth',t:'vs',u:'ortho',lv:1,k:'nat',name:'Pythagoras for vectors',sheet:R`x\perp y\Rightarrow\|x+y\|^2=\|x\|^2+\|y\|^2`,
 q:R`\(x\perp y\), \(\|x\|=5\), \(\|y\|=12\). Find \(\|x+y\|\).`,n:{v:13},
 why:R`\(\|x+y\|^2=25+2x^\top y+144=169\), and the cross term is 0.`},
{id:'cs',t:'vs',u:'ortho',lv:2,k:'bug',name:'Cauchy–Schwarz inequality',sheet:R`|x^\top y|\le\|x\|\,\|y\|`,
 f:R`|x^\top y|\ge\|x\|\,\|y\|`,
 o:[R`The inequality points the wrong way`,R`It should use \(\|x\|^2\|y\|^2\)`,R`It should be an equality`,R`Nothing, it is correct`],a:0,
 why:R`\(|\cos\theta|\le1\), so the dot product can't exceed the product of lengths. Equality holds when the vectors are parallel.`},

/* ---------- Matrices ---------- */
{id:'transp',t:'mat',u:'matops',lv:1,k:'bug',name:'Transpose of a product',sheet:R`(AB)^\top=B^\top A^\top`,
 f:R`(AB)^\top=A^\top B^\top`,
 o:[R`The order should reverse: \(B^\top A^\top\)`,R`It should be \(A^\top B\)`,R`Transposes don't distribute over products`,R`Nothing, it is correct`],a:0,
 why:R`The order reverses, same as for inverses. For non-square A and B, \(A^\top B^\top\) often isn't even defined.`},
{id:'invprod',t:'mat',u:'matops',lv:1,k:'fill',name:'Inverse of a product',sheet:R`(AB)^{-1}=B^{-1}A^{-1}`,
 f:R`(AB)^{-1}=\boxed{\;?\;}`,
 o:[R`B^{-1}A^{-1}`,R`A^{-1}B^{-1}`,R`A^{-1}+B^{-1}`,R`(BA)^{-1}`],om:1,a:0,
 why:R`Check: \(AB\,B^{-1}A^{-1}=A\,I\,A^{-1}=I\). Socks and shoes: undo the last step first.`},
{id:'inv2',t:'mat',u:'matops',lv:1,k:'fill',name:'Inverse of a 2×2 matrix',sheet:R`\begin{bmatrix}a&b\\c&d\end{bmatrix}^{-1}=\frac{1}{ad-bc}\begin{bmatrix}d&-b\\-c&a\end{bmatrix}`,
 f:R`\begin{bmatrix}a&b\\c&d\end{bmatrix}^{-1}=\frac{1}{ad-bc}\boxed{\;?\;}`,
 o:[R`\begin{bmatrix}d&-b\\-c&a\end{bmatrix}`,R`\begin{bmatrix}a&-b\\-c&d\end{bmatrix}`,R`\begin{bmatrix}d&b\\c&a\end{bmatrix}`,R`\begin{bmatrix}-d&b\\c&-a\end{bmatrix}`],om:1,a:0,
 why:R`Swap the diagonal, negate the off-diagonal, divide by the determinant.`},
{id:'trcyc',t:'mat',u:'trace',lv:1,k:'bug',name:'Trace of a product',sheet:R`\operatorname{tr}(AB)=\operatorname{tr}(BA)`,
 f:R`\operatorname{tr}(AB)=\operatorname{tr}(A)\operatorname{tr}(B)`,
 o:[R`Trace doesn't split over products; the true rule is \(\operatorname{tr}(AB)=\operatorname{tr}(BA)\)`,R`It should be \(\operatorname{tr}(A)+\operatorname{tr}(B)\)`,R`It holds for square matrices`,R`Nothing, it is correct`],a:0,
 why:R`Trace is linear (\(\operatorname{tr}(A+B)=\operatorname{tr}A+\operatorname{tr}B\)) and cyclic. Try \(A=B=I_2\): \(\operatorname{tr}(I)=2\), but \(2\times2=4\).`},
{id:'trshape',t:'mat',u:'trace',lv:2,k:'cond',name:'Cyclic property of trace',sheet:R`A\in\mathbb R^{m\times n},\ B\in\mathbb R^{n\times m}:\ \operatorname{tr}(AB)=\operatorname{tr}(BA)`,
 q:R`\(\operatorname{tr}(AB)=\operatorname{tr}(BA)\) holds whenever:`,
 o:[R`Both products are defined (A is m×n and B is n×m)`,R`A and B are square and commute`,R`A and B are symmetric`,R`A or B is invertible`],a:0,
 why:R`Both traces equal \(\sum_{i,j}a_{ij}b_{ji}\). Here AB is m×m and BA is n×n, yet the traces match. This gives \(x^\top Ax=\operatorname{tr}(Axx^\top)\).`},
{id:'gram',t:'mat',u:'symm',lv:2,k:'cond',name:'Gram matrix AᵀA',sheet:R`A^\top A\ \text{symmetric PSD};\ \text{PD}\iff\text{columns of }A\text{ independent}`,
 q:R`For a real matrix A, \(A^\top A\) is positive definite (hence invertible) when:`,
 o:[R`The columns of A are linearly independent`,R`A is square`,R`A has more columns than rows`,R`Always, for any A`],a:0,
 why:R`\(x^\top A^\top Ax=\|Ax\|^2\ge0\), with equality only if \(Ax=\mathbf 0\). Independent columns rule that out for \(x\ne\mathbf 0\). The matrix \(G_{ij}=x_i^\top x_j\) of independent vectors is such a Gram matrix.`},
{id:'symeig',t:'mat',u:'symm',lv:1,k:'mcq',name:'Real symmetric matrices',sheet:R`A=A^\top\Rightarrow\lambda\in\mathbb R,\ \text{orthogonal eigenvectors},\ A=Q\Lambda Q^\top`,
 q:R`Which is true for every real symmetric matrix?`,
 o:[R`Its eigenvalues are real, and it has an orthonormal set of eigenvectors`,R`Its eigenvalues are all positive`,R`It is invertible`,R`Its eigenvalues are all distinct`],a:0,
 why:R`This is the spectral theorem: \(A=Q\Lambda Q^\top\). Signs and repeats are unrestricted, and zero eigenvalues make it singular.`},
{id:'symvec',t:'mat',u:'symm',lv:2,k:'mcq',name:'Second eigenvector of a symmetric 2×2',sheet:R`A=A^\top,\ \lambda_1\ne\lambda_2\Rightarrow v_1\perp v_2`,
 q:R`A real symmetric 2×2 matrix with distinct eigenvalues has eigenvector \((1,2)\). Another eigenvector is:`,
 o:[R`\((2,-1)\)`,R`\((2,1)\)`,R`\((1,-2)\)`,R`\((1,1)\)`],a:0,
 why:R`Eigenvectors for different eigenvalues of a symmetric matrix are orthogonal, and \((1,2)\cdot(2,-1)=0\).`},
{id:'blockdet',t:'mat',u:'partition',lv:2,k:'fill',name:'Block triangular determinant',sheet:R`\det\begin{bmatrix}A&B\\0&D\end{bmatrix}=\det A\cdot\det D`,
 q:R`A and D are square blocks.`,f:R`\det\begin{bmatrix}A&B\\0&D\end{bmatrix}=\boxed{\;?\;}`,
 o:[R`\det A\,\det D`,R`\det A\,\det D-\det B`,R`\det(AD-B)`,R`\det A+\det D`],om:1,a:0,
 why:R`The zero block kills every term mixing the two diagonal blocks, so the off-diagonal block B doesn't matter. Eigenvalues are likewise those of A together with those of D.`},
{id:'blockinv',t:'mat',u:'partition',lv:2,k:'mcq',name:'Inverse of a block-diagonal matrix',sheet:R`\begin{bmatrix}A&0\\0&D\end{bmatrix}^{-1}=\begin{bmatrix}A^{-1}&0\\0&D^{-1}\end{bmatrix}`,
 q:R`For invertible square blocks A and D, the inverse of \(\begin{bmatrix}A&0\\0&D\end{bmatrix}\) is:`,
 o:[R`\(\begin{bmatrix}A^{-1}&0\\0&D^{-1}\end{bmatrix}\)`,R`\(\begin{bmatrix}D^{-1}&0\\0&A^{-1}\end{bmatrix}\)`,R`\(\begin{bmatrix}0&A^{-1}\\D^{-1}&0\end{bmatrix}\)`,R`\(\frac{1}{\det A\det D}\begin{bmatrix}D&0\\0&A\end{bmatrix}\)`],a:0,
 why:R`Blocks multiply like numbers when the shapes match, so invert each diagonal block in place.`},
{id:'blockmul',t:'mat',u:'partition',lv:2,k:'mcq',name:'Block multiplication',sheet:R`\begin{bmatrix}A&B\end{bmatrix}\begin{bmatrix}C\\D\end{bmatrix}=AC+BD`,
 q:R`With conformable blocks, \(\begin{bmatrix}A&B\end{bmatrix}\begin{bmatrix}C\\D\end{bmatrix}=\)`,
 o:[R`\(AC+BD\)`,R`\(CA+DB\)`,R`\(\begin{bmatrix}AC&BD\end{bmatrix}\)`,R`\(AD+BC\)`],a:0,
 why:R`Row of blocks times column of blocks, keeping each product in its order. In the same way \(AA^\top=\sum_i a_ia_i^\top\) over the columns \(a_i\).`},
{id:'r1eig',t:'mat',u:'rank1',lv:2,k:'fill',name:'Eigenvalues of uuᵀ',sheet:R`uu^\top:\ \lambda=u^\top u\ (\text{once}),\ 0\ (n-1\ \text{times})`,
 q:R`For non-zero \(u\in\mathbb R^n\), the only non-zero eigenvalue of \(uu^\top\) is:`,f:R`\lambda=\boxed{\;?\;}`,
 o:[R`u^\top u`,R`1`,R`\|u\|`,R`n`],om:1,a:0,
 why:R`\((uu^\top)u=u(u^\top u)\), so u is an eigenvector with eigenvalue \(\|u\|^2\). Anything orthogonal to u maps to 0. The rank is 1.`},
{id:'r1sv',t:'mat',u:'rank1',lv:2,k:'nat',name:'Singular values of uuᵀ',sheet:R`\sigma(uu^\top)=\{\|u\|^2,0,\dots,0\}`,
 q:R`\(u=(1,2,2)^\top\). Find the sum of the singular values of \(uu^\top\).`,n:{v:9},
 why:R`\(uu^\top\) is symmetric PSD, so its singular values equal its eigenvalues: \(u^\top u=9\) and two zeros.`},
{id:'detlemma',t:'mat',u:'rank1',lv:3,k:'nat',name:'Determinant of I + uuᵀ',sheet:R`\det(I+uu^\top)=1+u^\top u`,
 q:R`\(u=(1,1,1)^\top\). Find \(\det(I_3+uu^\top)\).`,n:{v:4},
 why:R`Eigenvalues of \(I+uu^\top\) are \(1+u^\top u=4\) (along u) and 1 (twice). The product is 4. So \(I+xx^\top\) with \(\|x\|=1\) is always invertible.`},

/* ---------- Special matrices ---------- */
{id:'orthdef',t:'special',u:'orthmat',lv:1,k:'fill',name:'Orthogonal matrix',sheet:R`Q^\top Q=QQ^\top=I\iff Q^{-1}=Q^\top`,
 f:R`Q\ \text{orthogonal}\iff Q^{-1}=\boxed{\;?\;}`,
 o:[R`Q^\top`,R`Q`,R`-Q`,R`\frac{1}{\det Q}Q`],om:1,a:0,
 why:R`The columns are orthonormal, so \(Q^\top Q=I\). Inverting is as cheap as transposing.`},
{id:'orthprops',t:'special',u:'orthmat',lv:2,k:'mcq',name:'What orthogonal matrices guarantee',sheet:R`\|Qx\|=\|x\|,\ \ |\det Q|=1,\ \ |\lambda|=1`,
 q:R`For a real orthogonal matrix Q, which statement is NOT always true?`,
 o:[R`All eigenvalues are \(+1\) or \(-1\)`,R`\(|\det Q|=1\)`,R`\(\|Qx\|=\|x\|\) for every x`,R`Q has full rank`],a:0,
 why:R`A 2D rotation by 90° is orthogonal but has eigenvalues \(\pm i\). What is guaranteed is \(|\lambda|=1\).`},
{id:'normpres',t:'special',u:'orthmat',lv:2,k:'cond',name:'Norm-preserving matrices',sheet:R`\|Ax\|=\|x\|\ \forall x\iff A^\top A=I`,
 q:R`A real square matrix A satisfies \(\|Ax\|_2=\|x\|_2\) for every x exactly when:`,
 o:[R`A is orthogonal`,R`\(A=I\)`,R`A is symmetric`,R`\(\det A=1\)`],a:0,
 why:R`\(\|Ax\|^2=x^\top A^\top Ax\) equals \(x^\top x\) for all x iff \(A^\top A=I\). Rotations and reflections both qualify, so A need not be I.`},
{id:'rotpow',t:'special',u:'orthmat',lv:2,k:'nat',name:'Powers of a rotation',sheet:R`R_\theta^k=R_{k\theta}`,
 q:R`M rotates the plane by \(2\pi/5\). Then \(M^{2027}=M^k\) for which \(k\in\{0,1,2,3,4\}\)?`,n:{v:2},
 why:R`\(M^5=I\), so only \(2027\bmod5\) matters: \(2027=5\times405+2\).`},
{id:'idemdef',t:'special',u:'idem',lv:1,k:'fill',name:'Idempotent matrix',sheet:R`P^2=P`,
 f:R`P\ \text{idempotent}\iff\boxed{\;?\;}`,
 o:[R`P^2=P`,R`P^2=I`,R`P^\top=P`,R`P^\top P=I`],om:1,a:0,
 why:R`Applying it twice is the same as once. \(P^2=I\) describes an involution, like a reflection.`},
{id:'idemeig',t:'special',u:'idem',lv:2,k:'mcq',name:'Eigenvalues of an idempotent matrix',sheet:R`P^2=P\Rightarrow\lambda\in\{0,1\},\ \operatorname{rank}P=\operatorname{tr}P`,
 q:R`If \(P^2=P\), every eigenvalue of P is:`,
 o:[R`0 or 1`,R`1 or −1`,R`Exactly 1`,R`Any real number`],a:0,
 why:R`\(Pv=\lambda v\Rightarrow P^2v=\lambda^2v=\lambda v\), so \(\lambda^2=\lambda\). The number of 1s is the rank, which also equals the trace.`},
{id:'idemtr',t:'special',u:'idem',lv:2,k:'nat',name:'Rank of an idempotent matrix',sheet:R`P^2=P\Rightarrow\operatorname{rank}(P)=\operatorname{tr}(P)`,
 q:R`A 6×6 matrix P satisfies \(P^2=P\) and \(\operatorname{tr}(P)=4\). Find \(\operatorname{rank}(P)\).`,n:{v:4},
 why:R`Idempotent matrices are diagonalisable with eigenvalues 0 and 1, so the trace counts the 1s, which is the rank.`},
{id:'idemcomp',t:'special',u:'idem',lv:2,k:'mcq',name:'Complement of an idempotent',sheet:R`P^2=P\Rightarrow(I-P)^2=I-P,\ \ P(I-P)=0`,
 q:R`If \(P^2=P\), then \(I-P\) is:`,
 o:[R`Also idempotent`,R`The inverse of P`,R`Always the zero matrix`,R`Orthogonal`],a:0,
 why:R`\((I-P)^2=I-2P+P^2=I-P\). For a projection, \(I-P\) projects onto the complementary space.`},
{id:'projA',t:'special',u:'projmat',lv:2,k:'fill',name:'Projection onto a column space',sheet:R`P=A(A^\top A)^{-1}A^\top`,
 q:R`A has independent columns. Projection onto its column space:`,f:R`P=A\,\boxed{\;?\;}\,A^\top`,
 o:[R`(A^\top A)^{-1}`,R`(AA^\top)^{-1}`,R`A^{-1}`,R`(A^\top A)`],om:1,a:0,
 why:R`From the normal equations \(\hat x=(A^\top A)^{-1}A^\top b\) and \(p=A\hat x\). With orthonormal columns it collapses to \(QQ^\top\).`},
{id:'projprop',t:'special',u:'projmat',lv:2,k:'mcq',name:'Orthogonal projection matrices',sheet:R`P^2=P,\ P^\top=P,\ \lambda\in\{0,1\}`,
 q:R`An orthogonal projection matrix P onto a subspace is always:`,
 o:[R`Symmetric and idempotent`,R`Orthogonal`,R`Invertible`,R`Skew-symmetric`],a:0,
 why:R`Projecting twice changes nothing, and orthogonality of the residual makes P symmetric. Unless it is I, it has a null space, so it is not invertible.`},
{id:'projnull',t:'special',u:'projmat',lv:2,k:'nat',name:'Null space of a projection',sheet:R`P\ \text{onto a }k\text{-dim subspace of }\mathbb R^n:\ \operatorname{rank}=k,\ \operatorname{nullity}=n-k`,
 q:R`P is the projection matrix onto a 2-dimensional subspace of \(\mathbb R^5\). Find the nullity of P.`,n:{v:3},
 why:R`P keeps the 2-dimensional subspace and sends its orthogonal complement (dimension 3) to zero.`},
{id:'centering',t:'special',u:'projmat',lv:3,k:'nat',name:'Centering matrix',sheet:R`C=I_n-\tfrac1n\mathbf 1\mathbf 1^\top:\ C^\top=C,\ C^2=C,\ \operatorname{tr}C=n-1`,
 q:R`\(C=I_8-\tfrac18\mathbf 1\mathbf 1^\top\). Find \(\operatorname{tr}(C)\).`,n:{v:7},
 why:R`C subtracts the mean, projecting onto vectors whose entries sum to 0. Each diagonal entry is \(1-\tfrac18\), giving \(8\cdot\tfrac78=7\), the rank. Its largest eigenvalue is 1.`},
{id:'projvecm',t:'special',u:'projmat',lv:1,k:'fill',name:'Projection onto a line',sheet:R`P=\frac{aa^\top}{a^\top a}`,
 f:R`P_{\text{onto }a}=\frac{aa^\top}{\boxed{\;?\;}}`,
 o:[R`a^\top a`,R`aa^\top`,R`\|a\|`,R`1`],om:1,a:0,
 why:R`The column-space formula with a single column. It has rank 1, and its non-zero eigenvalue is 1.`},

/* ---------- Determinant ---------- */
{id:'detprod',t:'det',u:'det',lv:1,k:'fill',name:'Determinant of a product',sheet:R`\det(AB)=\det A\,\det B,\ \ \det A^\top=\det A,\ \ \det A^{-1}=\tfrac{1}{\det A}`,
 f:R`\det(AB)=\boxed{\;?\;}`,
 o:[R`\det A\,\det B`,R`\det A+\det B`,R`\det(BA)^{-1}`,R`\det A\,\det B^\top-1`],om:1,a:0,
 why:R`Determinants multiply. So \(\det(AB)=\det(BA)\) even when \(AB\ne BA\).`},
{id:'detscale',t:'det',u:'det',lv:1,k:'fill',name:'Scaling a matrix',sheet:R`\det(cA)=c^n\det A\ \ (A\in\mathbb R^{n\times n})`,
 q:R`A is \(n\times n\).`,f:R`\det(cA)=\boxed{\;?\;}`,
 o:[R`c^n\det A`,R`c\det A`,R`nc\det A`,R`c^2\det A`],om:1,a:0,
 why:R`Each of the n rows is scaled by c, and each row scaling multiplies the determinant by c.`},
{id:'detsum',t:'det',u:'det',lv:1,k:'bug',name:'Determinant of a sum',sheet:R`\det(A+B)\ne\det A+\det B\ \text{in general}`,
 f:R`\det(A+B)=\det A+\det B`,
 o:[R`No such rule exists; the determinant isn't additive`,R`It should be \(\det A\,\det B\)`,R`It holds for 2×2 matrices`,R`Nothing, it is correct`],a:0,
 why:R`Try \(A=B=I_2\): \(\det(2I)=4\), but \(1+1=2\). The determinant is linear in each row separately, not in the whole matrix.`},
{id:'detrow',t:'det',u:'det',lv:1,k:'mcq',name:'Row operations and determinant',sheet:R`\text{swap}:\ \times(-1);\ \ \text{scale row by }c:\ \times c;\ \ R_i+kR_j:\ \text{unchanged}`,
 q:R`Which row operation leaves the determinant unchanged?`,
 o:[R`Adding a multiple of one row to another`,R`Swapping two rows`,R`Multiplying a row by 2`,R`Replacing a row by its negative`],a:0,
 why:R`That is why elimination keeps track only of swaps and scalings: the determinant ends up as ± the product of the pivots.`},
{id:'dettri',t:'det',u:'det',lv:1,k:'mcq',name:'Triangular determinant',sheet:R`\det(\text{triangular})=\prod_i a_{ii}`,
 q:R`The determinant of an upper triangular matrix is:`,
 o:[R`The product of its diagonal entries`,R`The sum of its diagonal entries`,R`Always 1`,R`The product of all entries`],a:0,
 why:R`Expanding down the first column leaves only the diagonal term each time. The diagonal entries are also the eigenvalues.`},
{id:'detcombo',t:'det',u:'det',lv:2,k:'nat',name:'Combining determinant rules',sheet:R`\det(cA^{-1}A^\top)=c^n\cdot\tfrac{1}{\det A}\cdot\det A`,
 q:R`A is 3×3 with \(\det A=5\). Find \(\det\big(2A^{-1}A^\top\big)\).`,n:{v:8},
 why:R`\(2^3\cdot\frac15\cdot5=8\). The transpose and inverse cancel each other's determinant.`},

/* ---------- Rank & nullity ---------- */
{id:'rankeq',t:'rank',u:'rank',lv:1,k:'mcq',name:'Row rank = column rank',sheet:R`\operatorname{rank}A=\operatorname{rank}A^\top=\operatorname{rank}A^\top A`,
 q:R`Which is always true for a real matrix A?`,
 o:[R`\(\operatorname{rank}A=\operatorname{rank}A^\top=\operatorname{rank}(A^\top A)\)`,R`\(\operatorname{rank}(A^\top A)=2\operatorname{rank}A\)`,R`\(\operatorname{rank}A\) equals the number of rows`,R`\(\operatorname{rank}A^\top\lt\operatorname{rank}A\) when A is tall`],a:0,
 why:R`Row rank and column rank always agree. \(A^\top A\) has the same null space as A, so it has the same rank.`},
{id:'rankprod',t:'rank',u:'rank',lv:2,k:'fill',name:'Rank of a product',sheet:R`\operatorname{rank}(AB)\le\min(\operatorname{rank}A,\operatorname{rank}B)`,
 f:R`\operatorname{rank}(AB)\le\boxed{\;?\;}`,
 o:[R`\min(\operatorname{rank}A,\operatorname{rank}B)`,R`\operatorname{rank}A+\operatorname{rank}B`,R`\max(\operatorname{rank}A,\operatorname{rank}B)`,R`\operatorname{rank}A\cdot\operatorname{rank}B`],om:1,a:0,
 why:R`The columns of AB lie in the column space of A, and its rows lie in the row space of B. Multiplying by an invertible matrix keeps the rank unchanged.`},
{id:'ranknat',t:'rank',u:'rank',lv:1,k:'nat',name:'Computing a rank',sheet:R`\operatorname{rank}=\text{number of pivots after elimination}`,
 q:R`Find the rank of \(\begin{bmatrix}1&2&3\\2&4&6\\1&1&1\end{bmatrix}\).`,n:{v:2},
 why:R`Row 2 is twice row 1. Rows 1 and 3 are independent, so the rank is 2.`},
{id:'rankzero',t:'rank',u:'rank',lv:1,k:'mcq',name:'Rank zero',sheet:R`\operatorname{rank}A=0\iff A=0`,
 q:R`A matrix has rank 0 exactly when:`,
 o:[R`It is the zero matrix`,R`It is singular`,R`Its determinant is 0`,R`It has a zero row`],a:0,
 why:R`Any non-zero entry gives a non-zero column, so the rank is at least 1. A matrix with a fixed non-zero entry can never have rank 0.`},
{id:'rnull',t:'rank',u:'nullity',lv:1,k:'fill',name:'Rank–nullity theorem',sheet:R`\operatorname{rank}(A)+\operatorname{nullity}(A)=n\ \ (n=\#\text{columns})`,
 q:R`A is \(m\times n\).`,f:R`\operatorname{rank}(A)+\operatorname{nullity}(A)=\boxed{\;?\;}`,
 o:[R`n`,R`m`,R`m+n`,R`\min(m,n)`],om:1,a:0,
 why:R`The null space lives in \(\mathbb R^n\), the input side. Every input direction is either killed or survives as a pivot direction.`},
{id:'rnullnat',t:'rank',u:'nullity',lv:1,k:'nat',name:'Nullity from rank',sheet:R`\operatorname{nullity}=n-\operatorname{rank}`,
 q:R`A is \(5\times7\) with rank 3. Find \(\dim N(A)\).`,n:{v:4},
 why:R`\(7-3=4\). The 5 rows don't enter; the left null space would be \(5-3=2\).`},
{id:'four',t:'rank',u:'fourspaces',lv:2,k:'mcq',name:'Orthogonal complements',sheet:R`C(A^\top)\perp N(A)\ \text{in }\mathbb R^n;\ \ C(A)\perp N(A^\top)\ \text{in }\mathbb R^m`,
 q:R`For \(A\in\mathbb R^{m\times n}\), which pair of subspaces are orthogonal complements?`,
 o:[R`Row space and null space`,R`Row space and column space`,R`Null space and left null space`,R`Column space and null space`],a:0,
 why:R`\(Ax=\mathbf 0\) says x is orthogonal to every row. The other complementary pair is the column space and the left null space, both in \(\mathbb R^m\).`},
{id:'leftnull',t:'rank',u:'fourspaces',lv:2,k:'fill',name:'Dimension of the left null space',sheet:R`\dim N(A^\top)=m-r`,
 q:R`A is \(m\times n\) with rank r.`,f:R`\dim N(A^\top)=\boxed{\;?\;}`,
 o:[R`m-r`,R`n-r`,R`r`,R`m+n-r`],om:1,a:0,
 why:R`Apply rank–nullity to \(A^\top\), which has m columns and the same rank r.`},

/* ---------- Linear systems ---------- */
{id:'consist',t:'sys',u:'systems',lv:1,k:'cond',name:'Consistency of Ax = b',sheet:R`Ax=b\ \text{solvable}\iff\operatorname{rank}A=\operatorname{rank}[A\mid b]`,
 q:R`The system \(Ax=b\) has at least one solution exactly when:`,
 o:[R`\(\operatorname{rank}A=\operatorname{rank}[A\mid b]\)`,R`A is square`,R`\(\det A\ne0\)`,R`\(b\ne\mathbf 0\)`],a:0,
 why:R`b must lie in the column space of A. Then appending b as a column doesn't raise the rank. \(\det A\ne0\) is sufficient but not necessary.`},
{id:'uniq',t:'sys',u:'systems',lv:1,k:'mcq',name:'Number of solutions',sheet:R`\text{consistent and }\operatorname{rank}A=n\Rightarrow\text{unique};\ \operatorname{rank}A\lt n\Rightarrow\infty`,
 q:R`\(Ax=b\) is consistent, A has n columns and \(\operatorname{rank}A\lt n\). The system has:`,
 o:[R`Infinitely many solutions`,R`Exactly one solution`,R`Exactly \(n-\operatorname{rank}A\) solutions`,R`No solution`],a:0,
 why:R`Any particular solution plus anything from the null space (dimension \(n-r\ge1\)) is also a solution.`},
{id:'wide',t:'sys',u:'systems',lv:2,k:'mcq',name:'Wide systems',sheet:R`A\in\mathbb R^{m\times n},\ m\lt n\Rightarrow\text{never a unique solution}`,
 q:R`A is \(2\times3\). The system \(Ax=b\) can:`,
 o:[R`Have no solution or infinitely many, but never exactly one`,R`Have exactly one solution for suitable b`,R`Always have exactly one solution`,R`Only have the zero solution`],a:0,
 why:R`The rank is at most 2, below the 3 unknowns, so the null space is non-trivial.`},
{id:'sqsys',t:'sys',u:'systems',lv:2,k:'mcq',name:'Square systems',sheet:R`A\in\mathbb R^{n\times n}:\ \text{unique for one } b\iff A\ \text{invertible}\iff\text{unique for all } b`,
 q:R`A is \(3\times3\) and \(Ax=p\) has a unique solution. Then for any other q, \(Ax=q\) has:`,
 o:[R`Exactly one solution`,R`Possibly infinitely many solutions`,R`Possibly no solution`,R`Only the zero solution`],a:0,
 why:R`A unique solution for one right-hand side means \(N(A)=\{\mathbf 0\}\). A square matrix with trivial null space is invertible, so \(x=A^{-1}q\) for every q.`},
{id:'homog',t:'sys',u:'homog',lv:1,k:'cond',name:'Non-trivial solutions of Ax = 0',sheet:R`Ax=\mathbf 0\ \text{has }x\ne\mathbf 0\iff\operatorname{rank}A\lt n\ (\iff\det A=0\ \text{if square})`,
 q:R`\(Ax=\mathbf 0\) (A square) has a non-zero solution exactly when:`,
 o:[R`\(\det A=0\)`,R`\(\det A\ne0\)`,R`A is symmetric`,R`A has a zero column on the diagonal`],a:0,
 why:R`A homogeneous system always has \(x=\mathbf 0\). Extra solutions exist iff the columns are dependent, i.e. A is singular.`},
{id:'rowsum',t:'sys',u:'homog',lv:2,k:'mcq',name:'Rows summing to 1',sheet:R`A\mathbf 1=\mathbf 1\Rightarrow p(A)\mathbf 1=p(1)\mathbf 1`,
 q:R`Each row of A sums to 1. Let \(B=A^2-A\). Then \(Bx=\mathbf 0\) has:`,
 o:[R`Infinitely many solutions`,R`Only \(x=\mathbf 0\)`,R`No solution`,R`Exactly two solutions`],a:0,
 why:R`\(A\mathbf 1=\mathbf 1\), so \(B\mathbf 1=\mathbf 1-\mathbf 1=\mathbf 0\). B has a non-zero null vector, and a homogeneous system with one has infinitely many.`},
{id:'gausscost',t:'sys',u:'gauss',lv:2,k:'mcq',name:'Cost of elimination',sheet:R`\text{elimination on }n\times n:\ O(n^3);\ \ \text{back substitution}:\ O(n^2)`,
 q:R`Solving \(Ux=b\) for an \(n\times n\) upper triangular U by back substitution takes:`,
 o:[R`\(O(n^2)\) operations`,R`\(O(n)\) operations`,R`\(O(n^3)\) operations`,R`\(O(n\log n)\) operations`],a:0,
 why:R`Row i needs about \(n-i\) multiply-adds, summing to \(n^2/2\). Reducing a full matrix to triangular form is the \(O(n^3)\) part.`},
{id:'pivots',t:'sys',u:'gauss',lv:1,k:'mcq',name:'Pivots and rank',sheet:R`\#\text{pivots}=\operatorname{rank};\ \det=\pm\prod\text{pivots}`,
 q:R`After Gaussian elimination, the number of pivots equals:`,
 o:[R`The rank`,R`The number of rows`,R`The nullity`,R`The trace`],a:0,
 why:R`Each pivot marks an independent row (and column). Free columns, those without pivots, count the nullity.`},

/* ---------- Eigenvalues ---------- */
{id:'charpoly',t:'eig',u:'eigdef',lv:1,k:'fill',name:'Characteristic equation',sheet:R`\det(A-\lambda I)=0`,
 f:R`\lambda\ \text{is an eigenvalue of }A\iff\boxed{\;?\;}`,
 o:[R`\det(A-\lambda I)=0`,R`\det(A)=\lambda`,R`A-\lambda I=0`,R`\operatorname{tr}(A)=\lambda`],om:1,a:0,
 why:R`\(Av=\lambda v\) with \(v\ne\mathbf 0\) means \(A-\lambda I\) has a non-trivial null space, i.e. it is singular.`},
{id:'eig2',t:'eig',u:'eigdef',lv:1,k:'nat',name:'Eigenvalues of a 2×2',sheet:R`\lambda^2-(\operatorname{tr}A)\lambda+\det A=0`,
 q:R`Find the larger eigenvalue of \(\begin{bmatrix}2&1\\1&2\end{bmatrix}\).`,n:{v:3},
 why:R`\(\lambda^2-4\lambda+3=0\Rightarrow\lambda=1,3\).`},
{id:'eigcomplex',t:'eig',u:'eigdef',lv:2,k:'mcq',name:'When 2×2 eigenvalues are complex',sheet:R`(\operatorname{tr}A)^2\lt4\det A\Rightarrow\text{complex conjugate pair}`,
 q:R`The eigenvalues of \(\begin{bmatrix}1&-2\\3&2\end{bmatrix}\) are:`,
 o:[R`A complex conjugate pair`,R`Real and distinct`,R`Real and equal`,R`One positive and one zero`],a:0,
 why:R`Trace 3, determinant \(2+6=8\). The discriminant \(9-32\lt0\).`},
{id:'sumeig',t:'eig',u:'eigprop',lv:1,k:'fill',name:'Sum of eigenvalues',sheet:R`\sum\lambda_i=\operatorname{tr}A,\ \ \prod\lambda_i=\det A`,
 f:R`\lambda_1+\lambda_2+\dots+\lambda_n=\boxed{\;?\;}`,
 o:[R`\operatorname{tr}(A)`,R`\det(A)`,R`\operatorname{rank}(A)`,R`\|A\|`],om:1,a:0,
 why:R`Compare the \(\lambda^{n-1}\) coefficient of the characteristic polynomial. The constant term gives \(\prod\lambda_i=\det A\).`},
{id:'othereig',t:'eig',u:'eigprop',lv:1,k:'nat',name:'Missing eigenvalue from the trace',sheet:R`\lambda_2=\operatorname{tr}A-\lambda_1`,
 q:R`\(H=\begin{bmatrix}7&-2\\-2&4\end{bmatrix}\) has one eigenvalue 3. Find the other.`,n:{v:8},
 why:R`Trace is 11, so the other is 8. Check: \(3\times8=24=\det H\).`},
{id:'deteig',t:'eig',u:'eigprop',lv:2,k:'nat',name:'Determinant from complex eigenvalues',sheet:R`\text{real }A:\ \text{complex eigenvalues come in conjugate pairs}`,
 q:R`A real 3×3 matrix has eigenvalues \(2-i\) and 3. Find \(\det A\).`,n:{v:15},
 why:R`The third eigenvalue must be \(2+i\). \(\det=(2-i)(2+i)\cdot3=5\cdot3=15\).`},
{id:'polyeig',t:'eig',u:'eigpoly',lv:1,k:'fill',name:'Eigenvalues of p(A)',sheet:R`Av=\lambda v\Rightarrow p(A)v=p(\lambda)v,\ \ A^{-1}v=\lambda^{-1}v`,
 q:R`\(Av=\lambda v\). For a polynomial p:`,f:R`p(A)\,v=\boxed{\;?\;}\,v`,
 o:[R`p(\lambda)`,R`\lambda`,R`p(1)\lambda`,R`p'(\lambda)`],om:1,a:0,
 why:R`Apply A repeatedly: \(A^kv=\lambda^kv\). Same eigenvectors, eigenvalues pushed through p. For \(A^{-1}\) you get \(1/\lambda\).`},
{id:'trpoly',t:'eig',u:'eigpoly',lv:2,k:'nat',name:'Trace of a matrix polynomial',sheet:R`\operatorname{tr}p(A)=\sum_i p(\lambda_i)`,
 q:R`A has eigenvalues 1, −2, 3. Find \(\operatorname{tr}(A^2-A)\).`,n:{v:12},
 why:R`\(p(\lambda)=\lambda^2-\lambda\) gives \(0,\ 6,\ 6\). Sum = 12.`},
{id:'detpoly',t:'eig',u:'eigpoly',lv:2,k:'nat',name:'Determinant of a matrix polynomial',sheet:R`\det p(A)=\prod_i p(\lambda_i)`,
 q:R`A has eigenvalues 1, 2, 3. Find \(\det(A^2+2A)\).`,n:{v:360},
 why:R`\(p(\lambda)=\lambda^2+2\lambda\) gives 3, 8, 15. Product = 360.`},
{id:'a2eq2a',t:'eig',u:'eigpoly',lv:2,k:'mcq',name:'Matrix equations restrict eigenvalues',sheet:R`p(A)=0\Rightarrow p(\lambda)=0\ \text{for every eigenvalue}`,
 q:R`A satisfies \(A^2=2A\). Every eigenvalue of A lies in:`,
 o:[R`\(\{0,2\}\)`,R`\(\{0,1\}\)`,R`\(\{1,2\}\)`,R`\(\{-2,2\}\)`],a:0,
 why:R`\(\lambda^2=2\lambda\Rightarrow\lambda\in\{0,2\}\). The same trick gives \(\{-1,0,1\}\) for \(A^3=A\).`},
{id:'trieig',t:'eig',u:'eigspecial',lv:1,k:'mcq',name:'Eigenvalues of a triangular matrix',sheet:R`\text{triangular }A:\ \lambda_i=a_{ii}`,
 q:R`The eigenvalues of an upper triangular matrix are:`,
 o:[R`Its diagonal entries`,R`All equal to its trace`,R`Its first-row entries`,R`Always real and positive`],a:0,
 why:R`\(A-\lambda I\) is triangular, so its determinant is \(\prod(a_{ii}-\lambda)\).`},
{id:'rot3',t:'eig',u:'eigspecial',lv:3,k:'nat',name:'Eigenvalues of a 3D rotation',sheet:R`\text{rotation by }t\text{ about an axis}:\ \lambda=1,\ e^{\pm it};\ \operatorname{tr}=1+2\cos t`,
 q:R`\(M=\begin{bmatrix}1&0&0\\0&\cos t&\sin t\\0&-\sin t&\cos t\end{bmatrix}\) with \(t=\pi/3\). Find the sum of its eigenvalues.`,n:{v:2},
 why:R`The sum equals the trace: \(1+2\cos(\pi/3)=1+1=2\). The eigenvalues are 1 and \(e^{\pm i\pi/3}\).`},
{id:'diagcond',t:'eig',u:'diag',lv:2,k:'cond',name:'Diagonalisability',sheet:R`A=PDP^{-1}\iff n\ \text{independent eigenvectors}`,
 q:R`An \(n\times n\) matrix A is diagonalisable exactly when:`,
 o:[R`It has n linearly independent eigenvectors`,R`It is invertible`,R`Its eigenvalues are all non-zero`,R`It has n distinct eigenvalues`],a:0,
 why:R`Distinct eigenvalues are sufficient but not necessary (I has one repeated eigenvalue and is diagonal). \(\begin{bmatrix}1&1\\0&1\end{bmatrix}\) is invertible but not diagonalisable.`},
{id:'diagpow',t:'eig',u:'diag',lv:1,k:'fill',name:'Powers via diagonalisation',sheet:R`A=PDP^{-1}\Rightarrow A^k=PD^kP^{-1}`,
 q:R`\(A=PDP^{-1}\) with D diagonal.`,f:R`A^k=\boxed{\;?\;}`,
 o:[R`PD^kP^{-1}`,R`P^kD^kP^{-k}`,R`PDP^{-1}k`,R`P^{-1}D^kP`],om:1,a:0,
 why:R`Inner \(P^{-1}P\) pairs cancel. Powering D just powers its diagonal.`},
{id:'abba',t:'eig',u:'diag',lv:3,k:'mcq',name:'Eigenvalues of AB and BA',sheet:R`AB\ \text{and}\ BA\ \text{share their non-zero eigenvalues}`,
 q:R`A is \(m\times n\) and B is \(n\times m\). The non-zero eigenvalues of AB and BA are:`,
 o:[R`The same`,R`Reciprocals of each other`,R`Unrelated`,R`The same only if A and B are square`],a:0,
 why:R`If \(ABv=\lambda v\) with \(\lambda\ne0\), then \(BA(Bv)=\lambda(Bv)\) and \(Bv\ne\mathbf 0\). This is why \(uu^\top\) has the same non-zero eigenvalue as the 1×1 matrix \(u^\top u\).`},
{id:'cayley',t:'eig',u:'cayley',lv:2,k:'fill',name:'Cayley–Hamilton (2×2)',sheet:R`A^2-(\operatorname{tr}A)A+(\det A)I=0`,
 q:R`Every 2×2 matrix satisfies its characteristic polynomial:`,f:R`A^2-(\operatorname{tr}A)\,A+\boxed{\;?\;}=0`,
 o:[R`(\det A)\,I`,R`(\operatorname{tr}A)\,I`,R`\det A`,R`A^{-1}`],om:1,a:0,
 why:R`Replace \(\lambda\) by A in \(\lambda^2-(\operatorname{tr}A)\lambda+\det A\). The constant becomes \((\det A)I\). Rearranged, this gives \(A^{-1}=\frac{(\operatorname{tr}A)I-A}{\det A}\).`},

/* ---------- Quadratic forms ---------- */
{id:'qfmat',t:'qf',u:'quadform',lv:1,k:'nat',name:'Matrix of a quadratic form',sheet:R`ax_1^2+2bx_1x_2+cx_2^2=x^\top\begin{bmatrix}a&b\\b&c\end{bmatrix}x`,
 q:R`Write \(Q(x)=2x_1^2+6x_1x_2+x_2^2\) as \(x^\top Ax\) with A symmetric. Find \(a_{12}\).`,n:{v:3},
 why:R`The cross term \(6x_1x_2\) is split evenly between \(a_{12}\) and \(a_{21}\).`},
{id:'pd',t:'qf',u:'quadform',lv:1,k:'cond',name:'Positive definiteness',sheet:R`A=A^\top\succ0\iff x^\top Ax>0\ \forall x\ne\mathbf 0\iff\lambda_i>0`,
 q:R`A symmetric matrix A is positive definite exactly when:`,
 o:[R`All its eigenvalues are positive`,R`All its entries are positive`,R`Its determinant is positive`,R`Its trace is positive`],a:0,
 why:R`Positive entries or a positive determinant don't suffice: \(\operatorname{diag}(-1,-1)\) has \(\det=1\). Equivalent test: all leading principal minors are positive (Sylvester).`},
{id:'indef',t:'qf',u:'quadform',lv:2,k:'mcq',name:'Classifying a 2×2 form',sheet:R`\det\lt0\Rightarrow\text{indefinite};\ \det>0,\ a>0\Rightarrow\text{PD}`,
 q:R`The quadratic form with matrix \(\begin{bmatrix}2&3\\3&1\end{bmatrix}\) is:`,
 o:[R`Indefinite`,R`Positive definite`,R`Negative definite`,R`Positive semidefinite`],a:0,
 why:R`\(\det=2-9=-7\lt0\), so the eigenvalues have opposite signs. Note \(a_{11}>0\) alone is not enough.`},
{id:'sylv',t:'qf',u:'quadform',lv:2,k:'mcq',name:'Sylvester’s criterion',sheet:R`A\succ0\iff\text{all leading principal minors}>0`,
 q:R`For which k is \(\begin{bmatrix}1&2\\2&k\end{bmatrix}\) positive definite?`,
 o:[R`\(k>4\)`,R`\(k>0\)`,R`\(k>2\)`,R`\(k\ge4\)`],a:0,
 why:R`The minors are 1 and \(k-4\). Both must be strictly positive. At \(k=4\) the matrix is only semidefinite.`},
{id:'rayl',t:'qf',u:'rayleigh',lv:2,k:'fill',name:'Rayleigh quotient',sheet:R`\max_{\|x\|=1}x^\top Ax=\lambda_{\max},\ \ \min_{\|x\|=1}x^\top Ax=\lambda_{\min}`,
 q:R`A is symmetric.`,f:R`\max_{\|x\|=1}x^\top Ax=\boxed{\;?\;}`,
 o:[R`\lambda_{\max}(A)`,R`\operatorname{tr}(A)`,R`\|A\|_F`,R`\det A`],om:1,a:0,
 why:R`Write \(x=\sum c_iq_i\) in the eigenbasis: \(x^\top Ax=\sum\lambda_ic_i^2\) with \(\sum c_i^2=1\). Put all weight on the top eigenvector. This is exactly the first principal component.`},
{id:'raylnat',t:'qf',u:'rayleigh',lv:2,k:'nat',name:'Maximising xᵀAx',sheet:R`\max_{\|x\|=1}x^\top Ax=\lambda_{\max}`,
 q:R`Find \(\max x^\top Ax\) over unit vectors x, for \(A=\begin{bmatrix}3&1\\1&3\end{bmatrix}\).`,n:{v:4},
 why:R`The eigenvalues are 4 and 2 (eigenvectors \((1,1)\) and \((1,-1)\)). The maximum is 4.`},

/* ---------- Projections & least squares ---------- */
{id:'projb',t:'proj',u:'projvec',lv:1,k:'fill',name:'Projection onto a vector',sheet:R`\operatorname{proj}_a b=\frac{a^\top b}{a^\top a}\,a`,
 f:R`\operatorname{proj}_a b=\frac{\boxed{\;?\;}}{a^\top a}\,a`,
 o:[R`a^\top b`,R`b^\top b`,R`\|a\|\|b\|`,R`ab^\top`],om:1,a:0,
 why:R`Choose \(c\) so the error \(b-ca\) is orthogonal to a: \(a^\top(b-ca)=0\Rightarrow c=a^\top b/a^\top a\).`},
{id:'projlen',t:'proj',u:'projvec',lv:2,k:'nat',name:'Length of a projection',sheet:R`\|\operatorname{proj}_a b\|=\frac{|a^\top b|}{\|a\|}`,
 q:R`Find the length of the projection of \(b=(3,1)\) onto \(a=(1,1)\), to 3 decimals.`,n:{v:2.8284,tol:0.002},
 why:R`\(a^\top b=4\), \(\|a\|=\sqrt2\), so the length is \(4/\sqrt2=2\sqrt2\approx2.828\). The projection itself is \((2,2)\).`},
{id:'normaleq',t:'proj',u:'lsq',lv:1,k:'fill',name:'Normal equations',sheet:R`A^\top A\hat x=A^\top b`,
 q:R`The least-squares solution of \(Ax\approx b\) satisfies:`,f:R`\boxed{\;?\;}\,\hat x=A^\top b`,
 o:[R`A^\top A`,R`AA^\top`,R`A`,R`A^{-1}`],om:1,a:0,
 why:R`The residual \(b-A\hat x\) must be orthogonal to every column of A: \(A^\top(b-A\hat x)=\mathbf 0\).`},
{id:'lsqw',t:'proj',u:'lsq',lv:2,k:'nat',name:'Least squares through the origin',sheet:R`y\approx wx:\ \hat w=\frac{\sum x_iy_i}{\sum x_i^2}`,
 q:R`Fit \(y=wx\) by least squares to \((1,2),(2,3),(3,5)\). Find \(\hat w\), to 3 decimals.`,n:{v:1.6429,tol:0.002},
 why:R`\(\sum xy=2+6+15=23\), \(\sum x^2=14\), so \(\hat w=23/14\approx1.643\).`},
{id:'resid',t:'proj',u:'lsq',lv:2,k:'mcq',name:'The least-squares residual',sheet:R`r=b-A\hat x\perp C(A),\ \ A^\top r=\mathbf 0`,
 q:R`At the least-squares solution, the residual \(b-A\hat x\) is:`,
 o:[R`Orthogonal to the column space of A`,R`Always zero`,R`Parallel to b`,R`In the column space of A`],a:0,
 why:R`\(A\hat x\) is the projection of b onto C(A), and what's left over is perpendicular to that space. It's zero only when b already lies in C(A).`},

/* ---------- Decompositions ---------- */
{id:'luform',t:'dec',u:'lu',lv:1,k:'mcq',name:'LU decomposition',sheet:R`A=LU,\ L\ \text{unit lower triangular},\ U\ \text{upper triangular}`,
 q:R`In \(A=LU\) from Gaussian elimination without row swaps, L holds:`,
 o:[R`The elimination multipliers below a diagonal of 1s`,R`The pivots on its diagonal`,R`The eigenvalues of A`,R`The inverse of U`],a:0,
 why:R`Each step subtracts \(\ell_{ij}\times\) row j from row i; those multipliers fill L. U is the final upper triangular matrix, with the pivots on its diagonal.`},
{id:'luexist',t:'dec',u:'lu',lv:2,k:'cond',name:'When LU exists',sheet:R`A=LU\ (\text{no pivoting})\iff\text{leading principal minors}\ne0`,
 q:R`An invertible A has an LU factorisation without row exchanges when:`,
 o:[R`All its leading principal submatrices are non-singular`,R`A is symmetric`,R`All its entries are non-zero`,R`Its trace is non-zero`],a:0,
 why:R`A zero pivot appears exactly when a leading principal minor is 0. Then you need a permutation: \(PA=LU\).`},
{id:'lusolve',t:'dec',u:'lu',lv:1,k:'mcq',name:'Solving with LU',sheet:R`Ax=b:\ Ly=b\ (\text{forward}),\ Ux=y\ (\text{back})`,
 q:R`Given \(A=LU\), to solve \(Ax=b\) you:`,
 o:[R`Solve \(Ly=b\) by forward substitution, then \(Ux=y\) by back substitution`,R`Solve \(Ux=b\), then \(Lx=y\)`,R`Invert L and U and multiply`,R`Compute \(\det L\cdot\det U\)`],a:0,
 why:R`\(LUx=b\): set \(y=Ux\). Each triangular solve is \(O(n^2)\), so new right-hand sides are cheap once A is factored.`},
{id:'lunat',t:'dec',u:'lu',lv:2,k:'nat',name:'Computing U in LU',sheet:R`u_{22}=a_{22}-\ell_{21}u_{12},\ \ \ell_{21}=a_{21}/a_{11}`,
 q:R`\(A=\begin{bmatrix}2&1\\6&5\end{bmatrix}=LU\). Find \(u_{22}\).`,n:{v:2},
 why:R`The multiplier is \(\ell_{21}=6/2=3\). Then \(u_{22}=5-3\times1=2\). Check: \(\det A=2\times2=4\).`},
{id:'svdform',t:'dec',u:'svd',lv:1,k:'fill',name:'Singular values',sheet:R`A=U\Sigma V^\top,\ \ \sigma_i=\sqrt{\lambda_i(A^\top A)}`,
 f:R`\sigma_i(A)=\sqrt{\lambda_i\big(\boxed{\;?\;}\big)}`,
 o:[R`A^\top A`,R`A`,R`A+A^\top`,R`A^{-1}`],om:1,a:0,
 why:R`\(A^\top A=V\Sigma^2V^\top\). Singular values are always real and non-negative, even when A's eigenvalues aren't.`},
{id:'svdrank',t:'dec',u:'svd',lv:1,k:'mcq',name:'SVD and rank',sheet:R`\operatorname{rank}A=\#\{\sigma_i>0\}`,
 q:R`The rank of A equals:`,
 o:[R`The number of non-zero singular values`,R`The largest singular value`,R`The sum of singular values`,R`The number of positive eigenvalues`],a:0,
 why:R`\(U\) and \(V\) are invertible, so A has the rank of \(\Sigma\). Counting positive eigenvalues fails for non-symmetric or indefinite matrices.`},
{id:'svdsym',t:'dec',u:'svd',lv:2,k:'mcq',name:'When singular values equal eigenvalues',sheet:R`A=A^\top:\ \sigma_i=|\lambda_i|;\ \ A\succeq0:\ \sigma_i=\lambda_i`,
 q:R`For a symmetric matrix A, the singular values are:`,
 o:[R`The absolute values of its eigenvalues`,R`Its eigenvalues, signs included`,R`The squares of its eigenvalues`,R`Unrelated to its eigenvalues`],a:0,
 why:R`\(A^\top A=A^2\) has eigenvalues \(\lambda_i^2\), so \(\sigma_i=|\lambda_i|\). For PSD matrices, such as \(\sum x_ix_i^\top\) with orthonormal \(x_i\), they coincide exactly.`},
{id:'svdnorm',t:'dec',u:'svd',lv:2,k:'nat',name:'Largest singular value',sheet:R`\|A\|_2=\sigma_{\max}`,
 q:R`Find the largest singular value of \(\begin{bmatrix}0&3\\-4&0\end{bmatrix}\).`,n:{v:4},
 why:R`\(A^\top A=\operatorname{diag}(16,9)\), so the singular values are 4 and 3. The eigenvalues of A are \(\pm i\sqrt{12}\); they don't give the answer.`},

/* ---------- Multiple select (MSQ) ---------- */
{id:'msqidem',t:'special',u:'idem',lv:2,k:'msq',name:'Idempotent matrices',sheet:R`P^2=P:\ \lambda\in\{0,1\},\ \operatorname{rank}=\operatorname{tr},\ (I-P)^2=I-P`,
 q:R`P is an \(n\times n\) matrix with \(P^2=P\). Which statements are always true?`,
 o:[R`Every eigenvalue of P is 0 or 1`,R`\(\operatorname{rank}(P)=\operatorname{tr}(P)\)`,R`\(I-P\) is idempotent`,R`P is invertible`],a:[0,1,2],
 ex:[R`\(\lambda^2=\lambda\).`,R`P is diagonalisable with eigenvalues 0 and 1; both sides count the 1s.`,R`\((I-P)^2=I-2P+P^2=I-P\).`,R`Only P = I is; any other idempotent has eigenvalue 0.`],
 why:R`Idempotents are projections (not necessarily orthogonal ones).`},
{id:'msqproj',t:'special',u:'projmat',lv:2,k:'msq',name:'Orthogonal projection onto a plane',sheet:R`P=P^\top=P^2,\ \operatorname{rank}=2,\ \operatorname{nullity}=1\ \text{in }\mathbb R^3`,
 q:R`P is the orthogonal projection matrix onto a 2-dimensional subspace of \(\mathbb R^3\). Which statements are true?`,
 o:[R`\(P^\top=P\)`,R`\(P^2=P\)`,R`The null space of P has dimension 1`,R`\(\det P=1\)`],a:[0,1,2],
 ex:[R`Orthogonal projections are symmetric.`,R`Projecting twice changes nothing.`,R`The normal direction to the plane is sent to 0.`,R`It has eigenvalue 0, so \(\det P=0\).`],
 why:R`Eigenvalues 1, 1, 0: symmetric, idempotent and singular.`},
{id:'msqorth',t:'special',u:'orthmat',lv:2,k:'msq',name:'Orthogonal matrices',sheet:R`Q^\top Q=I:\ Q^{-1}=Q^\top,\ |\det Q|=1,\ \|Qx\|=\|x\|,\ |\lambda|=1`,
 q:R`Q is a real orthogonal matrix. Which statements are always true?`,
 o:[R`\(Q^{-1}=Q^\top\)`,R`\(|\det Q|=1\)`,R`All eigenvalues of Q are real`,R`\(\|Qx\|=\|x\|\) for all x`],a:[0,1,3],
 ex:[R`Definition.`,R`\(\det(Q^\top Q)=(\det Q)^2=1\).`,R`A 90° rotation has eigenvalues \(\pm i\).`,R`\(x^\top Q^\top Qx=x^\top x\).`],
 why:R`Eigenvalues have modulus 1 but can be complex.`},
{id:'msqsym',t:'mat',u:'symm',lv:2,k:'msq',name:'Real symmetric matrices',sheet:R`A=A^\top:\ \lambda\in\mathbb R,\ A=Q\Lambda Q^\top`,
 q:R`A is a real symmetric matrix. Which statements are always true?`,
 o:[R`All eigenvalues are real`,R`Eigenvectors for distinct eigenvalues are orthogonal`,R`A is invertible`,R`A can be diagonalised by an orthogonal matrix`],a:[0,1,3],
 ex:[R`Spectral theorem.`,R`Also part of the spectral theorem.`,R`The zero matrix is symmetric.`,R`\(A=Q\Lambda Q^\top\).`],
 why:R`Symmetric says nothing about invertibility.`},
{id:'msqsub',t:'vs',u:'subsp',lv:2,k:'msq',name:'Which sets are subspaces',sheet:R`\text{subspace: contains }\mathbf0,\ \text{closed under }+\text{ and scalar }\times`,
 q:R`Which of these are subspaces of \(\mathbb R^3\)?`,
 o:[R`\(\{x: x_1+x_2+x_3=0\}\)`,R`\(\{x: x_1=1\}\)`,R`\(\operatorname{span}\{(1,0,0),(1,1,0)\}\)`,R`\(\{x: x_1x_2=0\}\)`],a:[0,2],
 ex:[R`The null space of a linear map.`,R`It misses \(\mathbf0\).`,R`Every span is a subspace.`,R`It's a union of two planes: \((1,0,0)+(0,1,0)\) leaves it.`],
 why:R`Homogeneous linear conditions and spans give subspaces; shifted or non-linear conditions don't.`},
{id:'msqsys',t:'sys',u:'systems',lv:3,k:'msq',name:'Possible solution patterns',sheet:R`\text{square: unique for one }b\iff\text{invertible};\ \text{wide: never unique}`,
 q:R`Which statements are true?`,
 o:[R`If a 3×3 system \(Ax=b\) has a unique solution for one b, then A is invertible`,R`A 2×3 system \(Ax=b\) can have a unique solution`,R`A 3×2 system can have a unique solution for one b and no solution for another`,R`\(Ax=\mathbf0\) always has at least one solution`],a:[0,2,3],
 ex:[R`Uniqueness means a trivial null space, and a square matrix with that is invertible.`,R`Rank ≤ 2 \(\lt\) 3 unknowns, so there are free variables.`,R`Full column rank gives uniqueness when consistent; b outside the column space gives none.`,R`\(x=\mathbf0\).`],
 why:R`Count rank against unknowns, and check whether b lies in the column space.`},
{id:'msqrank',t:'rank',u:'nullity',lv:2,k:'msq',name:'Rank, nullity and the four subspaces',sheet:R`A\in\mathbb R^{m\times n},\ \operatorname{rank}r:\ \dim N(A)=n-r,\ \dim N(A^\top)=m-r`,
 q:R`A is a 4×6 matrix with rank 3. Which statements are true?`,
 o:[R`\(\dim N(A)=3\)`,R`\(\dim N(A^\top)=1\)`,R`The columns of A are linearly independent`,R`\(\operatorname{rank}(A^\top)=3\)`],a:[0,1,3],
 ex:[R`\(6-3\).`,R`\(4-3\).`,R`Six columns, rank 3: dependent.`,R`Row rank equals column rank.`],
 why:R`Rank–nullity on A and on \(A^\top\).`},
{id:'msqeig',t:'eig',u:'eigprop',lv:2,k:'msq',name:'Reading facts off eigenvalues',sheet:R`\det=\prod\lambda,\ \operatorname{tr}=\sum\lambda,\ \lambda(A^k)=\lambda^k`,
 q:R`A 3×3 matrix A has eigenvalues 1, 2 and −3. Which statements are true?`,
 o:[R`\(\det A=-6\)`,R`\(\operatorname{tr}A=0\)`,R`A is invertible`,R`\(A^2\) has −9 as an eigenvalue`],a:[0,1,2],
 ex:[R`\(1\cdot2\cdot(-3)\).`,R`\(1+2-3\).`,R`No eigenvalue is 0.`,R`Squaring gives 1, 4 and 9.`],
 why:R`Products and sums of eigenvalues, and powers of them, answer most such questions.`},
{id:'msqpd',t:'qf',u:'quadform',lv:2,k:'msq',name:'A positive definite matrix',sheet:R`\begin{bmatrix}2&1\\1&2\end{bmatrix}:\ \lambda=3,1`,
 q:R`\(A=\begin{bmatrix}2&1\\1&2\end{bmatrix}\). Which statements are true?`,
 o:[R`A is positive definite`,R`\(x^\top Ax>0\) for every \(x\ne\mathbf0\)`,R`The maximum of \(x^\top Ax\) over unit vectors is 3`,R`\(\det A=4\)`],a:[0,1,2],
 ex:[R`Both eigenvalues (3 and 1) are positive.`,R`That's what positive definite means.`,R`The largest eigenvalue.`,R`\(4-1=3\).`],
 why:R`Eigenvalues 3 and 1 settle all four.`},
{id:'msqsvd',t:'dec',u:'svd',lv:2,k:'msq',name:'Singular values',sheet:R`\sigma_i\ge0,\ \#\{\sigma_i>0\}=\operatorname{rank},\ \sigma_{\max}=\|A\|_2`,
 q:R`Which statements about singular values are true for every real matrix A?`,
 o:[R`They are non-negative`,R`The number of non-zero singular values equals the rank`,R`They equal the absolute values of the eigenvalues whenever A is square`,R`The largest equals \(\max_{\|x\|=1}\|Ax\|\)`],a:[0,1,3],
 ex:[R`Square roots of the eigenvalues of \(A^\top A\).`,R`U and V are invertible.`,R`Only for symmetric (more generally normal) matrices; try \(\begin{bmatrix}0&1\\0&0\end{bmatrix}\).`,R`The spectral norm.`],
 why:R`Singular values come from \(A^\top A\), not from A's own eigenvalues.`},
{id:'msqiuu',t:'mat',u:'rank1',lv:3,k:'msq',name:'I − uuᵀ for a unit vector',sheet:R`\|u\|=1:\ I-uu^\top\ \text{projects onto }u^\perp;\ \lambda=0\ (\text{once}),1`,
 q:R`\(u\in\mathbb R^n\) is a unit vector and \(A=I-uu^\top\). Which statements are true?`,
 o:[R`A is idempotent`,R`A is invertible`,R`\(\operatorname{rank}(A)=n-1\)`,R`\(Au=\mathbf0\)`],a:[0,2,3],
 ex:[R`\(A^2=I-2uu^\top+u(u^\top u)u^\top=A\).`,R`It sends u to 0.`,R`It keeps the \((n-1)\)-dimensional complement of u.`,R`\(u-u(u^\top u)=\mathbf0\).`],
 why:R`Compare \(I+uu^\top\), which has eigenvalues 2 and 1 and is always invertible.`},

/* ---------- Depth pass ---------- */
{id:'spandim',t:'vs',u:'basis',lv:1,k:'nat',name:'Dimension of a span',sheet:R`\dim\operatorname{span}\{v_i\}=\operatorname{rank}[v_1\ \cdots\ v_k]`,
 q:R`Find the dimension of \(\operatorname{span}\{(1,2,3),(2,4,6),(0,1,1)\}\).`,n:{v:2},
 why:R`The second vector is twice the first, and the third isn't a multiple of it. Two independent vectors.`},
{id:'gsfill',t:'vs',u:'gramschmidt',lv:1,k:'fill',name:'Gram–Schmidt step',sheet:R`u_2=v_2-\frac{v_2^\top u_1}{u_1^\top u_1}u_1`,
 f:R`u_2=v_2-\frac{v_2^\top u_1}{\boxed{\;?\;}}\,u_1`,
 o:[R`u_1^\top u_1`,R`v_2^\top v_2`,R`\|u_1\|`,R`v_2^\top u_1`],om:1,a:0,
 why:R`Subtract the projection of \(v_2\) on \(u_1\), so what's left is orthogonal to \(u_1\). Normalise at the end for an orthonormal set.`},
{id:'gsnat',t:'vs',u:'gramschmidt',lv:2,k:'nat',name:'Gram–Schmidt by hand',sheet:R`u_2=v_2-\operatorname{proj}_{u_1}v_2`,
 q:R`Apply Gram–Schmidt to \(v_1=(1,1)\), \(v_2=(1,0)\) without normalising: \(u_1=v_1\), \(u_2=v_2-\frac{v_2^\top u_1}{u_1^\top u_1}u_1\). Find the second component of \(u_2\).`,n:{v:-0.5},
 why:R`\(\frac{v_2^\top u_1}{u_1^\top u_1}=\tfrac12\), so \(u_2=(1,0)-\tfrac12(1,1)=(0.5,-0.5)\). Check: \(u_2\cdot u_1=0\).`},
{id:'gsqr',t:'vs',u:'gramschmidt',lv:2,k:'mcq',name:'Gram–Schmidt and QR',sheet:R`A=QR:\ Q\ \text{orthonormal columns},\ R\ \text{upper triangular}`,
 q:R`Applying Gram–Schmidt to the (independent) columns of A gives \(A=QR\). Which is true?`,
 o:[R`Q has orthonormal columns and R is upper triangular`,R`Q is lower triangular and R is orthogonal`,R`Q and R are both diagonal`,R`R is symmetric`],a:0,
 why:R`Each column of A is a combination of the first few q's, which makes R upper triangular. QR is used for stable least squares.`},
{id:'tracenat',t:'mat',u:'trace',lv:1,k:'nat',name:'Trace of an outer product',sheet:R`\operatorname{tr}(xy^\top)=y^\top x`,
 q:R`\(x=(1,2,3)\), \(y=(4,0,-1)\). Find \(\operatorname{tr}(xy^\top)\).`,n:{v:1},
 why:R`The diagonal entries are \(x_iy_i\): \(4+0-3=1\). It's the dot product, by the cyclic property.`},
{id:'nullzero',t:'rank',u:'fourspaces',lv:1,k:'nat',name:'Full column rank',sheet:R`\operatorname{rank}=n\ (\#\text{columns})\Rightarrow N(A)=\{\mathbf 0\}`,
 q:R`A is a 5×3 matrix of rank 3. What is the dimension of its null space?`,n:{v:0},
 why:R`\(3-3=0\): the columns are independent, so \(Ax=\mathbf0\) only for \(x=\mathbf0\). Its left null space has dimension \(5-3=2\).`},
{id:'freevars',t:'sys',u:'homog',lv:1,k:'nat',name:'Free variables',sheet:R`\#\text{free variables}=n-\operatorname{rank}`,
 q:R`A homogeneous system has 3 independent equations in 5 unknowns. How many free variables does its solution have?`,n:{v:2},
 why:R`\(5-3=2\). The solution set is a 2-dimensional subspace.`},
{id:'multiplier',t:'sys',u:'gauss',lv:1,k:'nat',name:'Elimination multipliers',sheet:R`\ell_{i1}=a_{i1}/a_{11}`,
 q:R`Gaussian elimination on \(\begin{bmatrix}2&1&1\\4&-6&0\\-2&7&2\end{bmatrix}\). By what multiple of row 1 is row 2 reduced to clear its first entry?`,n:{v:2},
 why:R`\(4/2=2\): row 2 − 2 × row 1. For row 3 the multiplier is \(-2/2=-1\). These multipliers fill L in \(A=LU\).`},
{id:'roteig',t:'eig',u:'eigspecial',lv:2,k:'fill',name:'Eigenvalues of a 2D rotation',sheet:R`R_\theta=\begin{bmatrix}\cos\theta&-\sin\theta\\\sin\theta&\cos\theta\end{bmatrix}:\ \lambda=\cos\theta\pm i\sin\theta`,
 f:R`\lambda(R_\theta)=\cos\theta\pm\boxed{\;?\;}`,
 o:[R`i\sin\theta`,R`\sin\theta`,R`i\cos\theta`,R`1`],om:1,a:0,
 why:R`\(\lambda=e^{\pm i\theta}\). They're real only for \(\theta=0\) or \(\pi\); the trace \(2\cos\theta\) is their sum.`},
{id:'chnat',t:'eig',u:'cayley',lv:2,k:'nat',name:'Cayley–Hamilton in numbers',sheet:R`A^2=(\operatorname{tr}A)A-(\det A)I\ \ (2\times2)`,
 q:R`A is 2×2 with trace 5 and determinant 6. Then \(A^2=\alpha A+\beta I\). Find β.`,n:{v:-6},
 why:R`\(A^2-5A+6I=0\), so \(A^2=5A-6I\).`},
{id:'chinv',t:'eig',u:'cayley',lv:2,k:'mcq',name:'Inverse via Cayley–Hamilton',sheet:R`A^{-1}=\frac{(\operatorname{tr}A)I-A}{\det A}\ \ (2\times2)`,
 q:R`For an invertible 2×2 matrix A, Cayley–Hamilton gives \(A^{-1}=\)`,
 o:[R`\(\dfrac{(\operatorname{tr}A)I-A}{\det A}\)`,R`\(\dfrac{A-(\operatorname{tr}A)I}{\det A}\)`,R`\(\dfrac{A^\top}{\det A}\)`,R`\((\operatorname{tr}A)I-A\)`],a:0,
 why:R`Multiply \(A^2-(\operatorname{tr}A)A+(\det A)I=0\) by \(A^{-1}\) and rearrange. It agrees with the swap-and-negate formula.`},
{id:'raylmin',t:'qf',u:'rayleigh',lv:1,k:'mcq',name:'Minimum of xᵀAx',sheet:R`\min_{\|x\|=1}x^\top Ax=\lambda_{\min}`,
 q:R`For symmetric A, the minimum of \(x^\top Ax\) over unit vectors x is:`,
 o:[R`The smallest eigenvalue, reached at its eigenvector`,R`0`,R`\(\det A\)`,R`The smallest diagonal entry`],a:0,
 why:R`Same argument as the maximum. A diagonal entry \(e_i^\top Ae_i\) is one value of the quotient, so the smallest one is at least \(\lambda_{\min}\).`},
{id:'projzero',t:'proj',u:'projvec',lv:1,k:'mcq',name:'Zero projection',sheet:R`\operatorname{proj}_ab=\mathbf0\iff a^\top b=0`,
 q:R`The projection of b onto a non-zero vector a is the zero vector exactly when:`,
 o:[R`a and b are orthogonal`,R`a and b are parallel`,R`\(\|b\|\lt\|a\|\)`,R`b is a unit vector`],a:0,
 why:R`The coefficient is \(a^\top b/a^\top a\). If b is parallel to a, the projection is b itself.`},
/* ---------- Determinant: extended set ---------- */
{id:'detinv',t:'det',u:'det',lv:1,k:'fill',name:'Determinant of an inverse',sheet:R`\det(A^{-1})=\frac{1}{\det A},\quad\det(A^\top)=\det A`,
 q:R`A is invertible. Complete the identity.`,f:R`\det(A^{-1})=\boxed{\;?\;}`,
 o:[R`\frac{1}{\det A}`,R`-\det A`,R`\det A`,R`\det(A^\top)`],om:1,a:0,
 why:R`\(\det A\cdot\det(A^{-1})=\det(AA^{-1})=\det I=1\). The transpose keeps the determinant; the inverse takes its reciprocal.`},
{id:'detswap',t:'det',u:'det',lv:1,k:'mcq',name:'Swapping and scaling rows',sheet:R`\text{swap}:\times(-1);\ \ \text{row}\times k:\times k;\ \ \text{row}+c\cdot\text{row}:\times1`,
 q:R`B is obtained from A by swapping two rows and then multiplying one row by 3. Then \(\det B\) is:`,
 o:[R`\(-3\det A\)`,R`\(3\det A\)`,R`\(-\det A\)`,R`\(\det A+3\)`],a:0,
 why:R`The swap flips the sign and scaling one row multiplies the determinant by 3. Scaling the whole matrix by 3 would give \(3^n\det A\).`},
{id:'detfull',t:'det',u:'det',lv:1,k:'cond',name:'When the determinant is non-zero',sheet:R`\det A\ne0\iff A\text{ invertible}\iff\operatorname{rank}A=n\iff0\text{ is not an eigenvalue}`,
 q:R`For an \(n\times n\) matrix A, \(\det A\ne0\) exactly when:`,
 o:[R`A has rank n`,R`A is symmetric`,R`Every entry of A is non-zero`,R`\(\operatorname{tr}A\ne0\)`],a:0,
 why:R`A zero determinant means the columns are dependent. \(\begin{bmatrix}1&1\\1&1\end{bmatrix}\) is symmetric with non-zero entries and trace 2, yet singular.`},
{id:'detortho',t:'det',u:'det',lv:1,k:'mcq',name:'Determinant of an orthogonal matrix',sheet:R`Q^\top Q=I\Rightarrow\det Q=\pm1`,
 q:R`Q is a real orthogonal matrix. Which values can \(\det Q\) take?`,
 o:[R`Only \(+1\) or \(-1\)`,R`Only \(+1\)`,R`Any non-zero real number`,R`Any real number with \(|\det Q|\le1\)`],a:0,
 why:R`\((\det Q)^2=\det(Q^\top Q)=\det I=1\). Rotations have \(+1\), reflections \(-1\).`},
{id:'detskew',t:'det',u:'det',lv:2,k:'mcq',name:'Skew-symmetric matrix of odd order',sheet:R`A^\top=-A,\ n\text{ odd}\Rightarrow\det A=0`,
 q:R`A is a real \(5\times5\) matrix with \(A^\top=-A\). Then \(\det A\) is:`,
 o:[R`0`,R`Always positive`,R`Always negative`,R`1`],a:0,
 why:R`\(\det A=\det A^\top=\det(-A)=(-1)^5\det A=-\det A\), so \(\det A=0\). For even n it need not be 0.`},
{id:'detidem',t:'det',u:'det',lv:2,k:'mcq',name:'Determinant of an idempotent matrix',sheet:R`P^2=P\Rightarrow\det P\in\{0,1\};\ \det P=1\iff P=I`,
 q:R`\(P^2=P\) and \(P\ne I\). Then \(\det P\) is:`,
 o:[R`0`,R`1`,R`\(-1\)`,R`It depends on the size of P`],a:0,
 why:R`\((\det P)^2=\det P\), so it is 0 or 1. If it were 1, P would be invertible and \(P=P^{-1}P^2=P^{-1}P=I\).`},
{id:'detcomm',t:'det',u:'det',lv:2,k:'cond',name:'det(AB) and det(BA)',sheet:R`\det(AB)=\det A\det B=\det(BA)`,
 q:R`A and B are \(n\times n\) matrices. The equality \(\det(AB)=\det(BA)\) holds:`,
 o:[R`Always`,R`Only if \(AB=BA\)`,R`Only if A and B are invertible`,R`Only if A and B are symmetric`],a:0,
 why:R`Both sides equal \(\det A\cdot\det B\), a product of numbers, which commutes even when the matrices don’t.`},
{id:'deteigall',t:'det',u:['det','eigprop'],lv:1,k:'cond',name:'Determinant as the product of eigenvalues',sheet:R`\det A=\prod_i\lambda_i\ \ (\text{with multiplicity, complex ones included})`,
 q:R`\(\det A=\lambda_1\lambda_2\cdots\lambda_n\) (eigenvalues counted with multiplicity) holds for:`,
 o:[R`Every square matrix`,R`Only diagonalisable matrices`,R`Only symmetric matrices`,R`Only matrices with real eigenvalues`],a:0,
 why:R`Put \(\lambda=0\) in \(\det(\lambda I-A)=\prod_i(\lambda-\lambda_i)\). No diagonalisability is needed; for real A complex eigenvalues pair up, so the product is real.`},
{id:'msqdet',t:'det',u:'det',lv:2,k:'msq',name:'Determinant facts',sheet:R`\det(kA)=k^n\det A,\ \det(A^\top)=\det A,\ \det(AB)=\det A\det B`,
 q:R`A and B are real \(n\times n\) matrices. Which statements are always true?`,
 o:[R`\(\det(A^\top A)\ge0\)`,R`\(\det(-A)=(-1)^n\det A\)`,R`\(\det(A+B)=\det A+\det B\)`,R`If \(\det A=0\), then A has a zero row`],a:[0,1],
 ex:[R`\(\det(A^\top A)=(\det A)^2\ge0\).`,R`Each of the n rows is multiplied by \(-1\).`,R`False: \(A=B=I_2\) gives 4 on the left and 2 on the right.`,R`False: \(\begin{bmatrix}1&2\\2&4\end{bmatrix}\) is singular with no zero row.`],
 why:R`Determinants multiply but don’t add, and singular means dependent rows, not necessarily a zero row.`},
{id:'detblockf',t:'det',u:'detcalc',lv:2,k:'mcq',name:'Block triangular determinant',sheet:R`\det\begin{bmatrix}A&B\\0&D\end{bmatrix}=\det A\cdot\det D`,
 q:R`A and D are square blocks. \(\det\begin{bmatrix}A&B\\0&D\end{bmatrix}\) equals:`,
 o:[R`\(\det A\cdot\det D\)`,R`\(\det A\cdot\det D-\det B\)`,R`\(\det(AD-B)\)`,R`\(\det A+\det D\)`],a:0,
 why:R`With a zero block in the corner, B has no effect. Without that zero block there is no such simple product rule.`},
{id:'detlemmaf',t:'det',u:'detcalc',lv:3,k:'mcq',name:'Matrix determinant lemma',sheet:R`\det(I_n+uv^\top)=1+v^\top u`,
 q:R`u and v are vectors in \(\mathbb R^n\). \(\det(I_n+uv^\top)\) equals:`,
 o:[R`\(1+v^\top u\)`,R`\((1+v^\top u)^n\)`,R`\(1+n\,v^\top u\)`,R`1`],a:0,
 why:R`\(uv^\top\) has rank 1: eigenvalue \(v^\top u\) (eigenvector u) and 0 repeated \(n-1\) times. So \(I+uv^\top\) has eigenvalues \(1+v^\top u\) and 1, with product \(1+v^\top u\).`},
{id:'detarea',t:'det',u:'detcalc',lv:1,k:'mcq',name:'Determinant as an area',sheet:R`|\det[\,a\ \ b\,]|=\text{area of the parallelogram on }a,b`,
 q:R`The parallelogram with sides \((3,1)\) and \((1,2)\) has area:`,
 o:[R`5`,R`7`,R`6`,R`1`],a:0,
 why:R`\(\left|\det\begin{bmatrix}3&1\\1&2\end{bmatrix}\right|=|6-1|=5\). In 3D, \(|\det|\) is the volume of the parallelepiped.`},
{id:'adjf',t:'det',u:'adj',lv:1,k:'fill',name:'Inverse via the adjugate',sheet:R`A^{-1}=\frac{\operatorname{adj}A}{\det A},\quad A\,\operatorname{adj}A=(\det A)\,I`,
 q:R`A is invertible. Complete the formula.`,f:R`A^{-1}=\frac{\boxed{\;?\;}}{\det A}`,
 o:[R`\operatorname{adj}A`,R`\text{the cofactor matrix }C`,R`A^\top`,R`\operatorname{tr}A`],om:1,a:0,
 why:R`\(\operatorname{adj}A=C^\top\), the transpose of the cofactor matrix. Forgetting the transpose is the usual slip.`},
{id:'adjdetf',t:'det',u:'adj',lv:2,k:'fill',name:'Determinant of the adjugate',sheet:R`\det(\operatorname{adj}A)=(\det A)^{n-1}`,
 q:R`A is \(n\times n\). Complete the identity.`,f:R`\det(\operatorname{adj}A)=(\det A)^{\boxed{\;?\;}}`,
 o:[R`n-1`,R`n`,R`n+1`,R`-1`],om:1,a:0,
 why:R`Take determinants of \(A\,\operatorname{adj}A=(\det A)I\): \(\det A\cdot\det(\operatorname{adj}A)=(\det A)^n\).`},
{id:'cramerf',t:'det',u:'adj',lv:1,k:'mcq',name:'Cramer’s rule',sheet:R`x_i=\frac{\det A_i}{\det A}\ \ (A_i:\ \text{column }i\text{ replaced by }b)`,
 q:R`For \(Ax=b\) with \(\det A\ne0\), Cramer’s rule gives \(x_i\) as:`,
 o:[R`\(\det A_i/\det A\), where \(A_i\) is A with column i replaced by b`,R`\(\det A_i/\det A\), where \(A_i\) is A with row i replaced by \(b^\top\)`,R`\(\det A/\det A_i\)`,R`\(b_i/\det A\)`],a:0,
 why:R`Replace a column, not a row. It only applies when \(\det A\ne0\).`},

/* numeric determinant cards: new numbers every time (data/generators.js) */
{id:'det2',t:'det',u:'detcalc',lv:1,k:'nat',name:'Determinant of a 2×2',sheet:R`\det\begin{bmatrix}a&b\\c&d\end{bmatrix}=ad-bc`,
 q:R`Find \(\det\begin{bmatrix}4&3\\2&5\end{bmatrix}\).`,n:{v:14},
 why:R`\(4\cdot5-3\cdot2=14\).`},
{id:'det3',t:'det',u:'detcalc',lv:2,k:'nat',name:'Determinant of a 3×3',sheet:R`\det A=a_{11}C_{11}+a_{12}C_{12}+a_{13}C_{13}`,
 q:R`Find \(\det\begin{bmatrix}2&1&0\\1&3&1\\0&1&2\end{bmatrix}\).`,n:{v:8},
 why:R`Along row 1: \(2(6-1)-1(2-0)+0=8\).`},
{id:'dettri4',t:'det',u:'detcalc',lv:1,k:'nat',name:'Triangular matrix in numbers',sheet:R`\det(\text{triangular})=\prod_i a_{ii}`,
 q:R`Find \(\det\begin{bmatrix}2&5&-1&7\\0&-1&4&3\\0&0&3&8\\0&0&0&2\end{bmatrix}\).`,n:{v:-12},
 why:R`The entries above the diagonal don’t matter: \(2\cdot(-1)\cdot3\cdot2=-12\).`},
{id:'detrules',t:'det',u:'det',lv:2,k:'nat',name:'Determinant rules in numbers',sheet:R`\det(kA)=k^n\det A,\ \det(A^{-1})=\tfrac1{\det A},\ \det(\operatorname{adj}A)=(\det A)^{n-1}`,
 q:R`A is \(3\times3\) with \(\det A=4\). Find \(\det(2A^{-1})\).`,n:{v:2},
 why:R`\(2^3\cdot\tfrac14=2\).`},
{id:'detsing',t:'det',u:['detcalc','det'],lv:2,k:'nat',name:'Value that makes a matrix singular',sheet:R`A\text{ singular}\iff\det A=0`,
 q:R`For what x is \(\begin{bmatrix}x&6\\2&3\end{bmatrix}\) singular?`,n:{v:4},
 why:R`\(3x-12=0\Rightarrow x=4\).`},
{id:'detrowop',t:'det',u:'det',lv:2,k:'nat',name:'Row operations in numbers',sheet:R`\text{swap}:\times(-1);\ \ \text{row}\times k:\times k;\ \ \text{row}+c\cdot\text{row}:\times1`,
 q:R`\(\det A=6\). B is made from A by swapping rows 1 and 2, then multiplying row 3 by 2, then adding 3 × row 1 to row 2. Find \(\det B\).`,n:{v:-12},
 why:R`\(6\times(-1)\times2\times1=-12\).`},
{id:'detblock',t:'det',u:'detcalc',lv:2,k:'nat',name:'Block triangular in numbers',sheet:R`\det\begin{bmatrix}A&B\\0&D\end{bmatrix}=\det A\cdot\det D`,
 q:R`Find \(\det\begin{bmatrix}2&1&5&7\\1&3&2&1\\0&0&4&1\\0&0&2&3\end{bmatrix}\).`,n:{v:50},
 why:R`The lower-left block is zero: \(\det\begin{bmatrix}2&1\\1&3\end{bmatrix}\cdot\det\begin{bmatrix}4&1\\2&3\end{bmatrix}=5\times10=50\).`},
{id:'detlemmanat',t:'det',u:'detcalc',lv:3,k:'nat',name:'Matrix determinant lemma in numbers',sheet:R`\det(I_n+uv^\top)=1+v^\top u`,
 q:R`\(u=(1,2,3)^\top\), \(v=(2,0,1)^\top\). Find \(\det(I_3+uv^\top)\).`,n:{v:6},
 why:R`\(1+v^\top u=1+(2+0+3)=6\).`},
{id:'cofactor',t:'det',u:'adj',lv:2,k:'nat',name:'Cofactors and signs',sheet:R`C_{ij}=(-1)^{i+j}M_{ij}`,
 q:R`For \(A=\begin{bmatrix}1&2&3\\0&4&5\\1&0&6\end{bmatrix}\), find the cofactor \(C_{12}\).`,n:{v:5},
 why:R`\(M_{12}=\det\begin{bmatrix}0&5\\1&6\end{bmatrix}=-5\), and the sign \((-1)^{1+2}=-1\) gives \(C_{12}=5\).`},
{id:'cramer2',t:'det',u:'adj',lv:2,k:'nat',name:'Cramer’s rule in numbers',sheet:R`x=\frac{\det A_x}{\det A}`,
 q:R`Use Cramer’s rule on \(2x+y=5,\ x+3y=10\). Find x.`,n:{v:1},
 why:R`\(\det A=6-1=5\), \(\det A_x=\det\begin{bmatrix}5&1\\10&3\end{bmatrix}=5\), so \(x=1\).`},
{id:'detperm',t:'det',u:'detcalc',lv:3,k:'nat',name:'Reversal permutation matrix',sheet:R`\det J_n=(-1)^{n(n-1)/2}\ \ (J_n:\ \text{ones on the anti-diagonal})`,
 q:R`\(J_4\) is the \(4\times4\) matrix with ones on the anti-diagonal and zeros elsewhere. Find \(\det J_4\).`,n:{v:1},
 why:R`Reversing 4 rows takes \(\lfloor4/2\rfloor=2\) swaps, so the sign is \((-1)^2=1\).`},
{id:'deteigshift',t:'det',u:['det','eigprop'],lv:2,k:'nat',name:'det(A − kI) from eigenvalues',sheet:R`\det(A-kI)=\prod_i(\lambda_i-k)`,
 q:R`A is \(3\times3\) with eigenvalues 1, 2, 4. Find \(\det(A-3I)\).`,n:{v:2},
 why:R`\((1-3)(2-3)(4-3)=(-2)(-1)(1)=2\).`}

]);
})();
